import hashlib
import math
from statistics import NormalDist


def bucket(salt, uid):
    h = hashlib.sha256(f"{salt}:{uid}".encode()).hexdigest()
    return int(h[:8], 16) % 100


def varian(salt, uid, bobot):
    b = bucket(salt, uid)
    batas = 0
    for nama, persen in bobot.items():
        batas += persen
        if b < batas:
            return nama
    return None


def ringkas(log):
    pengguna, pembeli = {}, {}
    for e in log:
        v = e["varian"]
        pengguna.setdefault(v, set()).add(e["uid"])
        pembeli.setdefault(v, set())
        if e["beli"]:
            pembeli[v].add(e["uid"])
    hasil = {}
    for v in sorted(pengguna):
        n, x = len(pengguna[v]), len(pembeli[v])
        hasil[v] = {"n": n, "pembeli": x, "konversi": x / n}
    return hasil


def cek_srm(n_a, n_b, rasio=0.5):
    total = n_a + n_b
    e_a = total * rasio
    e_b = total - e_a
    chi2 = (n_a - e_a) ** 2 / e_a + (n_b - e_b) ** 2 / e_b
    p = math.erfc(math.sqrt(chi2 / 2))
    return {"chi2": chi2, "p": p, "srm": p < 0.001}


def uji_z(x_a, n_a, x_b, n_b):
    p_a, p_b = x_a / n_a, x_b / n_b
    p = (x_a + x_b) / (n_a + n_b)
    se = math.sqrt(p * (1 - p) * (1 / n_a + 1 / n_b))
    z = (p_b - p_a) / se
    return {"z": z, "p": 2 * (1 - NormalDist().cdf(abs(z)))}


def interval(x_a, n_a, x_b, n_b, tingkat=0.95):
    p_a, p_b = x_a / n_a, x_b / n_b
    se = math.sqrt(p_a * (1 - p_a) / n_a + p_b * (1 - p_b) / n_b)
    z = NormalDist().inv_cdf((1 + tingkat) / 2)
    d = p_b - p_a
    return (d - z * se, d + z * se)


def keputusan(ringkasan, guardrail_ok):
    a, b = ringkasan["A"], ringkasan["B"]
    if cek_srm(a["n"], b["n"])["srm"]:
        return "periksa data"
    bawah, atas = interval(a["pembeli"], a["n"], b["pembeli"], b["n"])
    if not guardrail_ok or atas < 0:
        return "jangan rilis"
    if bawah > 0:
        return "rilis"
    return "lanjutkan"


LOG = buat_log(lambda uid: varian("checkout-v2", uid, {"A": 50, "B": 50}))
HASIL = ringkas(LOG)
print(HASIL)
print(keputusan(HASIL, True))

