            g["total"] += e["total"]
    hasil = {}
    for v, g in grup.items():
        n, b = len(g["semua"]), len(g["beli"])
        hasil[v] = {
            "pengguna": n,
            "pembeli": b,
            "konversi": b / n,
            "rata_belanja": g["total"] / b if b else 0,
